<?php include 'verifica_login.php'; include 'conexao.php';$id=filter_input(INPUT_GET,'id',FILTER_VALIDATE_INT);if(!$id||$id<1)die('ID inválido.');mysqli_begin_transaction($conexao);try{if(!mysqli_query($conexao,"DELETE FROM artigo_autor WHERE id_artigo=$id"))throw new Exception(mysqli_error($conexao));if(!mysqli_query($conexao,"DELETE FROM artigos WHERE id_artigo=$id"))throw new Exception(mysqli_error($conexao));mysqli_commit($conexao);header('Location: lista_artigos.php');exit;}catch(Exception $e){mysqli_rollback($conexao);die('Não foi possível excluir o artigo: '.htmlspecialchars($e->getMessage()));}
